import{_ as r,o as n,c as s,ah as t}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Recherche: Walter Rosenkranz (Vorsitz im Pilnacek-Ausschuss)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/walter-rosenkranz.md","filePath":"recherche/walter-rosenkranz.md"}'),i={name:"recherche/walter-rosenkranz.md"};function a(o,e,h,u,d,l){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-walter-rosenkranz-vorsitz-im-pilnacek-ausschuss" tabindex="-1">Recherche: Walter Rosenkranz (Vorsitz im Pilnacek-Ausschuss) <a class="header-anchor" href="#recherche-walter-rosenkranz-vorsitz-im-pilnacek-ausschuss" aria-label="Permalink to &quot;Recherche: Walter Rosenkranz (Vorsitz im Pilnacek-Ausschuss)&quot;">​</a></h1><p><strong>Der neue Schiedsrichter im Archiv des Schweigens.</strong></p><p>Walter Rosenkranz (FPÖ) ist seit 2024 Nationalratspräsident und führt in dieser Funktion den Vorsitz im <strong>Pilnacek-Untersuchungsausschuss</strong> (2025–2026). Damit steht er im direkten Kontrast zu seinem Vorgänger Wolfgang Sobotka (ÖVP), der in diesem Ausschuss oft selbst im Zentrum der Vorwürfe steht.</p><hr><h2 id="die-rolle-im-u-ausschuss" tabindex="-1">Die Rolle im U-Ausschuss <a class="header-anchor" href="#die-rolle-im-u-ausschuss" aria-label="Permalink to &quot;Die Rolle im U-Ausschuss&quot;">​</a></h2><h3 id="_1-ein-novum-in-der-geschichte" tabindex="-1">1. Ein Novum in der Geschichte <a class="header-anchor" href="#_1-ein-novum-in-der-geschichte" aria-label="Permalink to &quot;1. Ein Novum in der Geschichte&quot;">​</a></h3><p>Zum ersten Mal in der Geschichte der Zweiten Republik führt ein FPÖ-Politiker den Vorsitz in einem Untersuchungsausschuss, der sich primär mit den Netzwerken der ÖVP befasst. Dies führt zu einer neuen Dynamik der Aufarbeitung – und zu heftigen Abwehrreaktionen der Volkspartei.</p><h3 id="_2-der-konflikt-mit-der-ovp" tabindex="-1">2. Der Konflikt mit der ÖVP <a class="header-anchor" href="#_2-der-konflikt-mit-der-ovp" aria-label="Permalink to &quot;2. Der Konflikt mit der ÖVP&quot;">​</a></h3><p>Rosenkranz wird von der ÖVP (insbesondere von Andreas Hanger) regelmäßig als „befangen“ und „politisch motiviert“ kritisiert. Die Inszenierung von Ortsterminen (wie an der Donau in Rossatz im Januar 2026) wird von Kritikern als „Show-Politik“ gewertet, während Befürworter von einem „neuen Standard der Transparenz“ sprechen.</p><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>Rosenkranz fungiert in unserer Mockumentary als der „unbequeme Zeremonienmeister“.</p><ul><li><strong>Der satirische Gegenspieler:</strong> Er ist derjenige, der Sobotka das Wort entzieht oder die „geheimen Tonbänder“ im Plenarsaal abspielen lässt.</li><li><strong>Acoustic Clash:</strong> Während Sobotka für das „Klavierspiel der Macht“ steht, steht Rosenkranz für das „Abspielen der Wahrheit“ (oder das, was die FPÖ dafür hält). In Teil 4 unseres Drehbuchs nutzen wir diesen Clash für das große Finale im Parlament.</li></ul><hr><p><em>Quellen: Protokolle des Nationalrats (2026), Berichterstattung zu den U-Ausschuss-Befragungen (OE24, ORF, heute.at).</em></p>',15)])])}const k=r(i,[["render",a]]);export{m as __pageData,k as default};
